INSERT INTO internship_listings (id, employer_id, title, description, location, is_remote, is_hybrid, compensation, requirements, key_responsibilities, industry, status, duration, application_deadline) VALUES
  ('fc000000-0000-4000-c000-000000000001', 'fb000000-0000-4000-b000-000000000001', 'Research Intern', 'Join Northwind Analytics as a Research Intern and work alongside an experienced team on meaningful projects. This is a hands-on role where you will contribute to real deliverables, learn industry tools, and grow your professional skills.', 'Denver, CO', false, false, 'Stipend', 'Pursuing a bachelor’s degree. Comfortable working both independently and in a team. Familiarity with common productivity and collaboration tools.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Technology', 'active', '3-6 months', '2026-07-29'),
  ('fc000000-0000-4000-c000-000000000002', 'fb000000-0000-4000-b000-000000000002', 'Content Intern', 'Vertex Robotics is looking for a motivated Content Intern to help drive our goals forward. You will collaborate across teams, present your work, and gain exposure to how a modern organization operates.', 'New York, NY', false, false, '$35-40/hr', 'Pursuing a bachelor’s degree. Comfortable working both independently and in a team. Familiarity with common productivity and collaboration tools.', 'Assist team members with research and analysis. Help maintain trackers and reports. Collaborate on cross-functional initiatives.', 'Engineering', 'active', null, '2026-08-26'),
  ('fc000000-0000-4000-c000-000000000003', 'fb000000-0000-4000-b000-000000000003', 'Communications Intern', 'Join Lumen Health Labs as a Communications Intern and work alongside an experienced team on meaningful projects. This is a hands-on role where you will contribute to real deliverables, learn industry tools, and grow your professional skills.', 'Boston, MA', false, true, '$40+/hr', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Healthcare', 'active', 'Fall Semester', null),
  ('fc000000-0000-4000-c000-000000000004', 'fb000000-0000-4000-b000-000000000004', 'Public Relations Intern', 'Cobalt Capital Group is looking for a motivated Public Relations Intern to help drive our goals forward. You will collaborate across teams, present your work, and gain exposure to how a modern organization operates.', 'Chicago, IL', false, false, '$25-30/hr', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Finance', 'active', 'Year-round', '2026-07-22'),
  ('fc000000-0000-4000-c000-000000000005', 'fb000000-0000-4000-b000-000000000005', 'Software Engineering Intern', 'This Software Engineering Intern position offers a structured program of learning and doing. At Brightline Media, interns are treated as full team members, attend planning sessions, and ship work that ships to real users.', 'Raleigh, NC', false, false, 'Unpaid', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Media', 'active', 'Fall Semester', null),
  ('fc000000-0000-4000-c000-000000000006', 'fb000000-0000-4000-b000-000000000006', 'QA Engineering Intern', 'This QA Engineering Intern position offers a structured program of learning and doing. At Evergreen Policy Institute, interns are treated as full team members, attend planning sessions, and ship work that ships to real users.', 'New York, NY', false, true, '$15-20/hr', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Nonprofit', 'active', '6+ months', '2026-08-21'),
  ('fc000000-0000-4000-c000-000000000007', 'fb000000-0000-4000-b000-000000000007', 'QA Engineering Intern', 'Join Summit Retail Co as a QA Engineering Intern and work alongside an experienced team on meaningful projects. This is a hands-on role where you will contribute to real deliverables, learn industry tools, and grow your professional skills.', 'Denver, CO', false, true, '$10-15/hr', 'Currently enrolled in a relevant degree program. Strong communication skills, attention to detail, and eagerness to learn. Prior project or coursework experience is a plus.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Retail', 'active', '6+ months', null),
  ('fc000000-0000-4000-c000-000000000008', 'fb000000-0000-4000-b000-000000000008', 'Customer Success Intern', 'As a Customer Success Intern at Pinnacle Legal Advisors, you will support day-to-day operations and take ownership of a focused project over the course of the internship. We pride ourselves on mentorship and giving interns real responsibility.', 'Remote', true, false, 'Stipend', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Assist team members with research and analysis. Help maintain trackers and reports. Collaborate on cross-functional initiatives.', 'Legal', 'active', null, null),
  ('fc000000-0000-4000-c000-000000000009', 'fb000000-0000-4000-b000-000000000009', 'Communications Intern', 'As a Communications Intern at Quantum Edge Software, you will support day-to-day operations and take ownership of a focused project over the course of the internship. We pride ourselves on mentorship and giving interns real responsibility.', 'Austin, TX', false, false, null, 'Currently enrolled in a relevant degree program. Strong communication skills, attention to detail, and eagerness to learn. Prior project or coursework experience is a plus.', 'Assist team members with research and analysis. Help maintain trackers and reports. Collaborate on cross-functional initiatives.', 'Technology', 'active', 'Summer', null),
  ('fc000000-0000-4000-c000-000000000010', 'fb000000-0000-4000-b000-000000000010', 'Social Media Intern', 'As a Social Media Intern at Harborview Biotech, you will support day-to-day operations and take ownership of a focused project over the course of the internship. We pride ourselves on mentorship and giving interns real responsibility.', 'Boston, MA', false, true, '$30-35/hr', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Healthcare', 'active', 'Spring Semester', null),
  ('fc000000-0000-4000-c000-000000000011', 'fb000000-0000-4000-b000-000000000011', 'Customer Success Intern', 'This Customer Success Intern position offers a structured program of learning and doing. At Ironclad Security, interns are treated as full team members, attend planning sessions, and ship work that ships to real users.', 'Chicago, IL', false, true, '$35-40/hr', 'Pursuing a bachelor’s degree. Comfortable working both independently and in a team. Familiarity with common productivity and collaboration tools.', 'Support active projects and contribute deliverables. Participate in team meetings and standups. Document work and present findings to stakeholders.', 'Technology', 'active', '3-6 months', '2026-05-30'),
  ('fc000000-0000-4000-c000-000000000012', 'fb000000-0000-4000-b000-000000000012', 'Public Relations Intern', 'As a Public Relations Intern at Meridian Consulting, you will support day-to-day operations and take ownership of a focused project over the course of the internship. We pride ourselves on mentorship and giving interns real responsibility.', 'Raleigh, NC', false, false, '$10-15/hr', 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Support active projects and contribute deliverables. Participate in team meetings and standups. Document work and present findings to stakeholders.', 'Finance', 'active', '3-6 months', '2026-08-12'),
  ('fc000000-0000-4000-c000-000000000013', 'fb000000-0000-4000-b000-000000000013', 'Operations Intern', 'Join Solstice Design Studio as a Operations Intern and work alongside an experienced team on meaningful projects. This is a hands-on role where you will contribute to real deliverables, learn industry tools, and grow your professional skills.', 'Remote', true, false, null, 'Currently enrolled in a relevant degree program. Strong communication skills, attention to detail, and eagerness to learn. Prior project or coursework experience is a plus.', 'Assist team members with research and analysis. Help maintain trackers and reports. Collaborate on cross-functional initiatives.', 'Media', 'active', '6+ months', '2026-07-26'),
  ('fc000000-0000-4000-c000-000000000014', 'fb000000-0000-4000-b000-000000000014', 'Communications Intern', 'Join Cedar & Co Marketing as a Communications Intern and work alongside an experienced team on meaningful projects. This is a hands-on role where you will contribute to real deliverables, learn industry tools, and grow your professional skills.', 'Raleigh, NC', false, true, null, 'Rising junior or senior preferred. Demonstrated initiative through coursework, clubs, or past internships. Ability to manage multiple priorities.', 'Own a focused project end-to-end. Provide regular status updates. Identify opportunities for improvement and propose solutions.', 'Marketing', 'active', null, '2026-07-03'),
